style.css:
@-moz-document domain("imgbb.com"), domain("ibb.co") {
:root {
    color-scheme: dark;
  }

  /* Base */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  body {
    background-image: none !important;
  }

  /* Soften every default light border to a subtle dark line */
  * {
    border-color: #262c33 !important;
  }

  /* Carets and tooltip arrows are CSS triangles (0x0 box, transparent unused sides) the blanket reset turns opaque. Restore transparency, tint only the triangle edge. */
  .arrow-down,
  .arrow-down-shadow,
  .arrow-up,
  .arrow-up-shadow,
  .arrow-left,
  .arrow-right {
    border-color: transparent !important;
  }

  .arrow-down,
  .arrow-down-shadow {
    border-top-color: #c4cdd6 !important;
  }

  .arrow-up,
  .arrow-up-shadow {
    border-bottom-color: #c4cdd6 !important;
  }

  .arrow-right {
    border-left-color: #c4cdd6 !important;
  }

  .arrow-left {
    border-right-color: #c4cdd6 !important;
  }

  /* Same triangle trick for the TipTip tooltip pointer. */
  #tiptip_arrow,
  #tiptip_arrow_inner {
    border-color: transparent !important;
  }

  #tiptip_holder.tip_top #tiptip_arrow_inner {
    border-top-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_bottom #tiptip_arrow_inner {
    border-bottom-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_right #tiptip_arrow_inner {
    border-right-color: rgba(0, 0, 0, 0.8) !important;
  }

  #tiptip_holder.tip_left #tiptip_arrow_inner {
    border-left-color: rgba(0, 0, 0, 0.8) !important;
  }

  /* The active nav item and the current sort tab are marked only by a 3px blue underline, flattened by the blanket reset. */
  .top-bar ul .pop-btn.current,
  .top-bar ul .top-btn-el.current,
  .content-tabs li.current,
  .content-tabs li:hover {
    border-color: #5fb0e6 !important;
  }

  /* Tab labels are color: inherit and the current tab is marked ONLY by the underline above, so link-blue makes all five read as active. */
  .content-tabs li a,
  .content-tabs li a span {
    color: #c4cdd6 !important;
  }

  .content-tabs li.current a,
  .content-tabs li.current a span {
    color: #e6edf3 !important;
  }

  .content-tabs li:hover a,
  .content-tabs li:hover a span {
    color: #9bd4ff !important;
  }

  /* The counter is a solid #d90000 pill labelled #fff. Must stay LAST: it ties with the tab-label rules on specificity. */
  .content-tabs li a span.tab-count-block {
    color: #ffffff !important;
  }

  /* Visited is a different state, not a second active one: no underline, orange-red label. */
  .content-tabs li.visited {
    border-bottom-color: transparent !important;
  }

  .content-tabs li.visited a {
    color: #ff7b72 !important;
  }

  .content-tabs li.current.visited {
    border-color: #ff7b72 !important;
  }

  /* Headings / text */
  h1, h2, h3, h4, h5, h6,
  .phone-text-align-center,
  .text-dark,
  strong, b {
    color: #e6edf3 !important;
  }

  p, span, li, dd, dt, label, small, td, th, figcaption {
    color: #c4cdd6 !important;
  }

  .text-muted,
  .sub-text,
  .light-text,
  .input-label-meta,
  .meta,
  time {
    color: #8b949e !important;
  }

  /* The one muted-text class ImgBB ships (#777, tuned for a white page); none of the names above exist on this site. */
  .input-below {
    color: #8b949e !important;
  }

  /* The only marker on a validation error, and the generic span colour reaches it. Empty until validation runs. */
  .red-warning,
  .input-warning.red-warning {
    color: #ff7b72 !important;
  }

  /* Links */
  a {
    color: #5fb0e6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* Nav links stay neutral, not link-blue. Must stay scoped to .top-bar: `.header` here is the CONTENT header (title, tabs, action row) and would outrank every .btn colour below, pinning each control's ink through :hover. */
  .top-bar a,
  .top-bar-logo a {
    color: #c4cdd6 !important;
  }

  .top-bar a:hover {
    color: #e6edf3 !important;
  }

  /* Off home and /upload the label is a nested span whose generic colour outranks the anchor's hovered ink. Matching the nested span keeps out the "Create account" chip, where .top-btn-text IS the anchor. */
  .top-bar a:hover span.top-btn-text {
    color: inherit !important;
  }

  /* These nav items are spans, not links; the site tints them and their caret on hover AND while the menu is open, and the neutral nav colour above beats both. Scoped to .pop-btn/.opened so the "Create account" chip keeps its white label. */
  .top-bar .pop-btn:hover .top-btn-text,
  .top-bar .opened .top-btn-text {
    color: #9bd4ff !important;
  }

  .top-bar .pop-btn:hover .arrow-down,
  .top-bar .opened .arrow-down {
    border-top-color: #9bd4ff !important;
  }

  /* A bare <span class="icon"> must inherit its item to track hover and open states; the generic span colour beats that inheritance. Keep scoped to .top-btn-text: the filmstrip's a.left-0 arrow glyph is page ink and would go blue. */
  .top-btn-text .icon {
    color: inherit !important;
  }

  /* Top bar / header */
  .top-bar,
  .header-top-bar {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
  }

  /* The header paints its real surface through a ::before layer (default rgba(255,255,255,0.9) frosted band). */
  #top-bar::before,
  .top-bar::before,
  .header-top-bar::before {
    background-color: #0d1117 !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .top-bar a,
  .top-bar-logo,
  .top-bar .text {
    color: #c4cdd6 !important;
  }

  /* Pop-out menus (account / language / share dropdowns) */
  .pop-box,
  .pop-box-inner,
  .pop-box-menu,
  .pop-box-menucols,
  .dropdown,
  .dropdown-menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.55) !important;
  }

  /* Phone build: pop-outs become a slide-in panel with a hard-coded white <ul>, plus a #eee bar on each bottom sheet. */
  #menu-fullscreen > ul {
    background-color: #1c2128 !important;
  }

  .pop-box-header {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* In a pop-out these are the menu's own pointer tip: menu surface colour, not the caret glyph colour above. */
  .pop-box .arrow-up {
    border-bottom-color: #1c2128 !important;
  }

  .pop-box .arrow-down {
    border-top-color: #1c2128 !important;
  }

  /* CSS triangle: colour ONLY the edge facing the menu, or the opposite border paints a diamond. */
  .pop-box::before,
  .pop-box::after,
  .arrow-box::before,
  .arrow-box::after {
    border-color: transparent !important;
  }

  .arrow-box-top::before,
  .arrow-box-top::after {
    border-bottom-color: #1c2128 !important;
  }

  .arrow-box-bottom::before,
  .arrow-box-bottom::after {
    border-top-color: #1c2128 !important;
  }

  .pop-box a,
  .pop-box-menu a,
  .dropdown a {
    color: #c4cdd6 !important;
  }

  .pop-box a:hover,
  .pop-box-menu a:hover,
  .dropdown a:hover {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* The selected row (e.g. active language) keeps a near-white highlight pill; give it a dark selected surface. */
  .pop-box .current a,
  .pop-box-menu .current a,
  .pop-box li.current > a {
    background-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  /* Main surfaces / panels */
  .content-width,
  .content-listing-container,
  .home-content,
  main,
  .page-content {
    background-color: transparent !important;
  }

  .panel,
  .panel-box,
  .box,
  .well,
  .image-viewer-sidebar,
  .sidebar,
  .modal,
  .modal-inner,
  .modal-box,
  .fullscreen-modal,
  .fullscreen-modal-box,
  #fullscreen-modal-box,
  .lightbox-content,
  .page-not-found,
  .empty-content,
  .content-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Dismissing a touched "Edit" dialog swaps its body for a #fff confirm strip. */
  #fullscreen-changes-confirm {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Section headers ("Share", "Embed codes", related blocks) */
  .header,
  .header-content {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }

  /* The sort-tab header is sticky with a near-opaque surface that the transparent .header rule above also matches. Below phablet the tab <ul> carries it. */
  .header.follow-scroll,
  .follow-scroll-wrapper.position-fixed,
  .header ul.content-tabs {
    background-color: #14181d !important;
  }

  .header .header-content-title,
  .header h1,
  .header h2 {
    color: #e6edf3 !important;
  }

  /* The title is an <a> the site pins to page ink; the generic link colour is a direct declaration that beats the inherited heading colour. `.top-user` is the same pattern outside .header's reach. */
  .header h1 a,
  .header .heading a,
  .header .header-content-title a,
  .top-user h1 a {
    color: inherit !important;
  }

  /* A #fff plate under the <img>, seen while it loads or through avatar transparency. */
  .top-user img.user-image {
    background-color: #0d1117 !important;
  }

  /* The site hover-tints the <b>/<span> children, not the anchor, and the generic element colours beat it. */
  a.number-figures:hover,
  a.number-figures:hover b,
  a.number-figures:hover span {
    color: #9bd4ff !important;
  }

  /* Upload landing */
  .upload-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .upload-box-inner,
  .upload-box-heading,
  .upload-box-status {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* On /upload the box is an empty in-flow shell (its heading is position:fixed) that the site keeps transparent; a surface here is a bare band under the top bar. */
  body#upload .upload-box,
  #upload #anywhere-upload {
    background-color: transparent !important;
  }

  /* An icon FONT, so the generic span colour repaints it. Keep it ImgBB blue. */
  .upload-box-heading .icon {
    color: #3a8fd6 !important;
  }

  /* Outcome utilities on the same glyph; the hero rule above is a descendant selector and outranks them. */
  .upload-box-heading .icon.color-green,
  .icon.color-green {
    color: #4ecb7d !important;
  }

  .upload-box-heading .icon.color-red,
  .icon.color-red {
    color: #ff7b72 !important;
  }

  /* The headline <a> is pinned to page ink by the site (a second file-picker target); the sub-links beneath it are the only blue the panel should carry. The generic link colour beats that inheritance. */
  .upload-box-heading .heading a,
  .upload-box-heading h2 a {
    color: inherit !important;
  }

  /* Neutral chrome, not a link: the site's #333 is dark-on-dark here and the generic link colour reaches the anchor. The label/glyph spans take the anchor's colour. */
  .upload-box-close {
    color: #c4cdd6 !important;
  }

  .upload-box-close a {
    color: inherit !important;
  }

  .home-buttons,
  .home-content {
    background-color: transparent !important;
  }

  /* "About / Pro account" promo + pricing tiers on the landing page */
  .about,
  .inner-cover {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  .pricing-tier-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .pricing-tier-price,
  .pricing-tier-box .header,
  .pricing-tier-box h1,
  .pricing-tier-box h2,
  .pricing-tier-box h3 {
    color: #e6edf3 !important;
  }

  /* Despite the name these set NO background: each only overrides the plan heading's 10px border-top, the pricing table's whole colour code. */
  .pricing-tier-box .header,
  .pricing-tier-box .background-red,
  .pricing-tier-box .background-blue,
  .pricing-tier-box .background-grey {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* ...and re-tint that accent bar, flattened by the blanket reset. */
  .pricing-tier-box .background-red {
    border-top-color: #e74c3c !important;
  }

  .pricing-tier-box .background-blue {
    border-top-color: #2a80b9 !important;
  }

  .pricing-tier-box .background-green {
    border-top-color: #27ae60 !important;
  }

  .pricing-tier-box .background-orange {
    border-top-color: #f39c12 !important;
  }

  .pricing-tier-box .background-purple {
    border-top-color: #9b59b6 !important;
  }

  .pricing-tier-box .background-yellow {
    border-top-color: #f1c40f !important;
  }

  /* #bdc3c7 natively - muted so the "no discount" tier is not a bright bar. */
  .pricing-tier-box .background-grey {
    border-top-color: #8b949e !important;
  }

  .pricing-tier-box .background-midnight {
    border-top-color: #44586c !important;
  }

  /* The site clears the separator on li:last-child so the list ends flush with the card; the blanket reset hands the line back. */
  .pricing-tier-box li:last-child {
    border-bottom-color: transparent !important;
  }

  /* Only the inner rotated div is the flag - .pricing-ribbon itself is an overflow-hidden clip window and colouring it fills the whole corner. */
  .pricing-ribbon > div {
    background-color: #a3261b !important;
    color: #ffffff !important;
  }

  /* The big drag-and-drop hero / drop overlay */
  .anywhere-upload-input-overlay,
  .anywhere-upload-input,
  .drop-zone,
  .dragging-overlay {
    background-color: rgba(13, 17, 23, 0.92) !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Queue tiles default to flat #efefef, glaring while the preview renders and for letterboxed images. The preview paints on top. */
  .queue-item,
  .queue-output {
    background-color: #0d1117 !important;
  }

  /* Solid white circles punching two bright dots over every thumbnail. */
  .queue-item-button,
  .queue-item-button.edit,
  .queue-item-button.cancel {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Translucent-white empty track; the coloured fill segment keeps its own inline width. */
  .queue-item .progress-bar {
    background-color: #2d333b !important;
  }

  /* A finished tile gets a .result overlay: white check on success, red triangle behind a white veil on failure; the generic span colour repaints both glyphs alike. */
  .upload-box-queue .failed .result {
    background-color: rgba(13, 17, 23, 0.72) !important;
  }

  .upload-box-queue .result .icon {
    color: #e6edf3 !important;
  }

  .upload-box-queue .failed .result .icon {
    color: #ff7b72 !important;
  }

  /* Image viewer stage */
  .image-viewer,
  .image-viewer-main,
  .image-viewer-container,
  .full-viewer,
  .viewer-image,
  .image-viewer-content {
    background-color: #0d1117 !important;
  }

  .image-viewer-main img,
  .viewer-image img {
    background-color: transparent !important;
  }

  /* Defaults to a near-white frosted bar; the thumbnail <img>s keep their own pixels. */
  .panel-thumbs,
  .panel-thumbs.follow-scroll {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  .panel-thumbs .arrow,
  .panel-thumbs-prev,
  .panel-thumbs-next,
  .panel-thumbs [class*="arrow"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Slots are #fff tiles with the images at opacity .25 - the site fades non-current thumbs INTO their tile, so fade them into the strip. */
  #panel-thumb-list li,
  .panel-thumb-list li {
    background-color: #0d1117 !important;
    /* The 3px transparent spacing border becomes an opaque line under every thumbnail under the blanket reset. */
    border-bottom-color: transparent !important;
  }

  /* One solid glyph on a flat plate, barely a shade apart - the near-match is what makes it read as a placeholder. Keep it near the 3:1 non-text floor; the generic span colour lands directly and would push it to 8:1. Photo avatars use background-image. */
  .user-image.default-user-image,
  .default-user-image {
    background-color: #2d333b !important;
    color: #767f8b !important;
  }

  .default-user-image .icon {
    color: inherit !important;
  }

  /* Image listing / thumbnail grid (albums, related) */
  .list-item,
  .pad-image-listing,
  .image-container,
  .image-container-main {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The site keeps this overlay TRANSPARENT and leans on a text-shadow; a surface here crops the bottom of every thumbnail. Over a photo the label stays white, not link-blue. */
  .list-item-desc {
    background-color: transparent !important;
  }

  .list-item-desc,
  .list-item-desc a,
  .list-item-desc-title-link {
    color: #ffffff !important;
  }

  .list-item-image,
  .image-container .image,
  .img-poster {
    background-color: #0d1117 !important;
  }

  .list-item-desc-fade {
    background-image: linear-gradient(to bottom, rgba(28, 33, 40, 0), #1c2128) !important;
  }

  /* Strip and slots are light plates the photos only partly cover; under five images leaves bare squares. Only a profile's /albums tab renders it. */
  .list-item-thumbs,
  .list-item-thumbs li {
    background-color: #1c2128 !important;
  }

  /* The lightbox root carries BOTH .viewer and .list-item, so the tile-surface rule above would paint its backdrop card grey. Must come AFTER that group - they tie on specificity. */
  .viewer {
    background-color: #0d1117 !important;
  }

  /* The name is a <span> for guest uploads but an <a class="user-name"> for registered ones, so the generic span and link colours both beat .viewer-owner's inherited #fff. The registered branch only exists on an account's album. */
  .viewer-owner .user-name {
    color: #ffffff !important;
  }

  .viewer-owner a.user-name:hover {
    color: rgba(255, 255, 255, 0.8) !important;
  }

  /* Empty-listing template: a #e5e5e5 ghost glyph the generic span colour would hand full body ink, and a #444 message line dark-on-dark here. */
  .content-empty,
  .content-empty .message {
    color: #8b949e !important;
  }

  .content-empty .icon {
    color: #262c33 !important;
  }

  /* The site paints the hovered page number #f6f6f6, which the link-hover blue above would sit on. */
  .content-listing-pagination a:hover {
    background-color: #21262d !important;
    color: #9bd4ff !important;
  }

  /* Not a target - the site strips its hover surface and the rule above would hand one back. */
  .content-listing-pagination .pagination-current a:hover {
    background-color: transparent !important;
  }

  /* Static content pages (API docs, plugin, terms) */
  /* .code is a 2px #ecf0f1 mat around the response textarea; inline <code> is a #f9f9f9 pill that swallows its own light label. */
  .code {
    background-color: #2d333b !important;
  }

  .text-content code {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* Password-protected content gate */
  /* "Private (password protected)" serves its own page type (body#password-gate), unlinked from the public site. */
  .content-password-gate,
  .access-box-content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .content-password-gate h1,
  .content-password-gate h1 .icon {
    color: #e6edf3 !important;
  }

  /* Tabbed share / embed-code panel */
  .tabbed-content,
  .panel-share,
  .panel-share-item,
  .tabs-content,
  .tabs-menu {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .tabs-menu a,
  .tabbed-content-nav a {
    color: #8b949e !important;
    border-color: #2d333b !important;
  }

  .tabs-menu a.active,
  .tabs-menu li.active a,
  .tabbed-content-nav a.active {
    color: #e6edf3 !important;
    border-bottom-color: #5fb0e6 !important;
  }

  /* A muted #bbb group caption sits over full-page-ink field labels; our heading and muted-label colours swap the two. */
  .panel-share-item h4.pre-title {
    color: #8b949e !important;
  }

  .panel-share-input-label {
    color: #c4cdd6 !important;
  }

  /* Below phablet the embed-code nav collapses to one .tab-menu button the site paints a flat #eee pill. */
  .tab-menu {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Forms / inputs (link + embed-code fields) */
  input,
  textarea,
  select,
  .text-input,
  .input-text,
  .form-input input {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }

  input::placeholder,
  textarea::placeholder,
  .text-input::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Darken the empty track only; the coloured fill segment keeps its own inline width/colour. */
  .input-password-strength {
    background-color: #2d333b !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    border-color: #5fb0e6 !important;
  }

  /* Input "copy" addon group around the share/embed fields */
  .input-with-buttons,
  .input-buttons,
  .copy-hover-display {
    background-color: transparent !important;
  }

  /* A span painted the page background to cut the rule line behind it, so it has to track the base colour. */
  .or-separator span {
    background-color: #14181d !important;
    color: #8b949e !important;
  }

  /* Buttons */
  /* The /plugin page's live preview of the visitor's own button: a page <style> gives each of the twelve palettes its own fill. Excluded so those rules paint it; a flat surface renders all twelve identically. */
  .btn,
  button:not(.imgbb-button),
  input[type="button"],
  input[type="submit"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .btn:hover,
  button:not(.imgbb-button):hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* The COPY chip needs a lighter plate than the generic button surface: #21262d inside the #0d1117 field is 1.2:1. Ties on specificity, so it must follow it. */
  button.input-action {
    background-color: #3b444f !important;
    color: #e6edf3 !important;
  }

  button.input-action:hover {
    background-color: #4a5563 !important;
    color: #ffffff !important;
  }

  /* Its 1px rgba(0,0,0,.05) hairline bevel becomes an opaque box around the swatch under the blanket reset. */
  .imgbb-button {
    border-color: rgba(0, 0, 0, 0.05) !important;
  }

  /* Bare spans the palette rules never name: they must inherit the button's colour, which flips to #000 on the two light-grey palettes. */
  .imgbb-button span {
    color: inherit !important;
  }

  /* Semantic action classes (.blue primary, .green upload/share, .red destructive) the flat .btn surface collapses into one grey. Darkened just enough for the white label to clear 4.5:1. */
  .btn.blue {
    background-color: #2a7ab0 !important;
    border-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  .btn.blue:hover {
    background-color: #24699a !important;
    color: #ffffff !important;
  }

  .btn.green {
    background-color: #1e8449 !important;
    border-color: #1e8449 !important;
    color: #ffffff !important;
  }

  .btn.green:hover {
    background-color: #1a7440 !important;
    color: #ffffff !important;
  }

  .btn.red {
    background-color: #b93226 !important;
    border-color: #b93226 !important;
    color: #ffffff !important;
  }

  .btn.red:hover {
    background-color: #a52c21 !important;
    color: #ffffff !important;
  }

  .btn.orange {
    background-color: #b8530b !important;
    border-color: #b8530b !important;
    color: #ffffff !important;
  }

  .btn.orange:hover {
    background-color: #a4490a !important;
    color: #ffffff !important;
  }

  /* Transparent chips with a coloured label. Restore that after the filled colours above. */
  .btn.outline,
  .btn.plain {
    background-color: transparent !important;
  }

  .btn.plain {
    border-color: transparent !important;
  }

  .btn.blue.outline {
    color: #5fb0e6 !important;
    border-color: #2a7ab0 !important;
  }

  .btn.green.outline {
    color: #4ecb7d !important;
    border-color: #1e8449 !important;
  }

  .btn.red.outline {
    color: #ff7b72 !important;
    border-color: #b93226 !important;
  }

  .btn.grey.outline,
  .btn.white.outline {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* The filled :hover colours above are more specific and would paint the chip its own accent, leaving the label sitting on itself. */
  .btn.outline:hover,
  .btn.plain:hover {
    background-color: transparent !important;
  }

  .btn.blue.outline:hover {
    color: #9bd4ff !important;
    border-color: #5fb0e6 !important;
  }

  .btn.green.outline:hover {
    color: #6ee29a !important;
    border-color: #4ecb7d !important;
  }

  .btn.red.outline:hover {
    color: #ff9d96 !important;
    border-color: #ff7b72 !important;
  }

  /* A disabled control says so almost entirely through its label. After the filled/outline :hover rules so it wins the tie. */
  .btn.disabled,
  .btn.disabled:hover {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #6e7681 !important;
  }

  .btn.disabled.outline,
  .btn.disabled.outline:hover {
    background-color: transparent !important;
    border-color: #2d333b !important;
    color: #6e7681 !important;
  }

  /* Like / share action pills keep semantic accents */
  .btn-like,
  .liked {
    color: #ff7b72 !important;
  }

  /* Every control's label and glyph are these span children, which the generic span colour repaints grey before any .btn colour reaches them. */
  .btn-icon,
  .btn-text,
  .sign-text {
    color: inherit !important;
  }

  /* Brand fill, white label; the generic `a` colour would leak link-blue onto them. */
  .sign-service,
  .link-service {
    color: #ffffff !important;
  }

  /* The site paints the glyph #fff over the brand fill, the generic `a` colour beats it, and .btn-icon inheritance then carries link-blue into every glyph. */
  .btn-social,
  .btn-social .btn-icon {
    color: #ffffff !important;
  }

  /* Mail is the one chip the site puts on a light grey fill, with a dark glyph. */
  .btn-social.btn-mail,
  .btn-social.btn-mail .btn-icon {
    color: #333333 !important;
  }

  /* Edit is link-blue, Delete destructive red, Approve green - the greys above flatten all three. */
  a.link span,
  a.link .icon {
    color: inherit !important;
  }

  a.link--delete,
  [data-action="delete"] {
    color: #ff7b72 !important;
  }

  a.link--approve {
    color: #4ecb7d !important;
  }

  /* Both are more specific than the generic link hover, so without these Edit brightens under the pointer while its neighbours stay flat. */
  a.link--delete:hover,
  [data-action="delete"]:hover {
    color: #ff9d96 !important;
  }

  a.link--approve:hover {
    color: #6ee29a !important;
  }

  /* Tables */
  table, tr, td, th {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  thead th,
  .table-header {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  tbody tr:hover {
    background-color: #1c2128 !important;
  }

  /* Footer */
  .footer,
  footer {
    background-color: #0d1117 !important;
    border-top: 1px solid #262c33 !important;
    color: #8b949e !important;
  }

  /* Muted to the footer's own grey they would be darker than the sentence around them, with no cue that they are links. */
  .footer a {
    color: #5fb0e6 !important;
  }

  .footer a:hover {
    color: #9bd4ff !important;
  }

  /* Misc */
  hr {
    border-color: #262c33 !important;
  }

  ::selection {
    background-color: #2a7ab0 !important;
    color: #ffffff !important;
  }

  .phone-hr,
  .divider {
    background-color: #262c33 !important;
  }

  /* Notification / flash bars stay readable */
  .alert,
  .notification {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Pale-yellow notice fields the site pairs with dark body text, which our generic ink repaints light. Dark amber keeps them reading as a notice. */
  .highlight,
  .growl {
    background-color: #33291a !important;
    color: #e6edf3 !important;
  }

  .highlight *,
  .growl * {
    color: #e6edf3 !important;
  }

  /* The left edge is the toast's severity accent, flattened by the blanket reset. */
  .growl {
    border-left-color: #f39c12 !important;
  }
}
